import math

def isDigitorialPermutation(n: int) -> bool:
    facts = [math.factorial(i) for i in range(10)]
    digits = [int(d) for d in str(n)]
    fact_sum = sum(facts[d] for d in digits)
    return sorted(str(n)) == sorted(str(fact_sum))

#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    bool isDigitorialPermutation(int n) {
        std::vector<int> facts(10, 1);
        for (int i = 1; i < 10; ++i) facts[i] = facts[i - 1] * i;
        std::string s = std::to_string(n);
        int factSum = 0;
        for (char c : s) factSum += facts[c - '0'];
        std::string sFact = std::to_string(factSum);
        std::sort(s.begin(), s.end());
        std::sort(sFact.begin(), sFact.end());
        return s == sFact;
    }
};

import java.util.*;

class Solution {
    public boolean isDigitorialPermutation(int n) {
        int[] facts = new int[10];
        facts[0] = 1;
        for (int i = 1; i < 10; i++) facts[i] = facts[i - 1] * i;
        String s = String.valueOf(n);
        int factSum = 0;
        for (char c : s.toCharArray()) factSum += facts[c - '0'];
        String sFact = String.valueOf(factSum);
        char[] a1 = s.toCharArray();
        char[] a2 = sFact.toCharArray();
        Arrays.sort(a1);
        Arrays.sort(a2);
        return Arrays.equals(a1, a2);
    }
}

